{
  "cards": [
    {
      "id": "independent-consequence",
      "norm": "consequential usefulness",
      "description": "Share of settled selected consequences that are paid off.",
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 10,
        "per": null
      },
      "region": {
        "rule": "at least",
        "lo": 0.5
      },
      "observation": "consequence_paid_off_rate",
      "answers_for": "producer",
      "reason": "Paid-off consequences provide evidence of value beyond internal approval, while the threshold avoids treating activity alone as usefulness."
    },
    {
      "id": "forecast-calibration-skill",
      "norm": "epistemic integrity",
      "description": "Mean selected forecast Brier score minus its paired pre-outcome prevalence-baseline Brier score.",
      "units": "score difference",
      "window": {
        "kind": "forecasts",
        "n": 25,
        "per": "assembly"
      },
      "region": {
        "rule": "at least",
        "lo": 0
      },
      "observation": "forecast_skill",
      "answers_for": "evaluator",
      "reason": "Requiring forecasts to improve on a prevalence baseline rewards evidence-responsive judgment rather than confident but uninformative predictions."
    },
    {
      "id": "bounded-compute-burn",
      "norm": "durable agency",
      "description": "Compute spend in each closed window, including retained-storage rent.",
      "units": "micro-USD per window",
      "window": {
        "kind": "windows",
        "n": 10,
        "per": null
      },
      "region": {
        "rule": "at most",
        "hi": 10000000
      },
      "observation": "burn_per_window",
      "answers_for": "all",
      "reason": "A visible spending ceiling encourages preserving resources for future worthwhile choices without implying that every capability-building expense is wasteful."
    },
    {
      "id": "avoidable-outside-cost-proxy",
      "norm": "bounded reciprocity",
      "description": "Peak observed absolute marked notional on one coin divided by starting equity.",
      "units": "ratio",
      "window": {
        "kind": "windows",
        "n": 10,
        "per": null
      },
      "region": {
        "rule": "at most",
        "hi": 1
      },
      "observation": "position_concentration",
      "answers_for": "producer",
      "reason": "Limiting concentrated exposure is a cautious, measurable proxy for constraining risk that could spill onto others, though it cannot establish consent or capture every external cost."
    },
    {
      "id": "fidelity-countercheck",
      "norm": "fidelity",
      "description": "Share of selected settled consequences that are paid off; interpret alongside documented consequences and treat missing measurement as unmeasured, not failure.",
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 10,
        "per": null
      },
      "region": {
        "rule": "at least",
        "lo": 0.5
      },
      "observation": "consequence_paid_off_rate",
      "answers_for": "all",
      "reason": "This consequence measure is defeasible evidence, so it should be read against supported outcomes and never let an absent sample count as a failing value."
    }
  ]
}

{
  "cards": [
    {
      "id": "consequence-uptake-floor",
      "norm": "consequential usefulness",
      "description": "Paid-off rate of independently settled consequences; a card whose favorable reading can only be sustained by consequences an independent counterparty actually settled.",
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 6,
        "per": "assembly"
      },
      "region": {
        "rule": "at least",
        "lo": 0.45
      },
      "observation": "consequence_paid_off_rate",
      "answers_for": "producer",
      "reason": "Uptake by an independent counterparty, not internal applause, is the evidence the norm demands, so the card reads the paid-off rate of consequences settled outside the producer's own lineage."
    },
    {
      "id": "commitment-resolution-ceiling",
      "norm": "epistemic integrity",
      "description": "Attributable, avoidably unresolved accepted commitments over the eligible commitments due in the responsible scope; a promise the seat quietly let lapse is a violation even when nothing measured it.",
      "units": "fraction",
      "window": {
        "kind": "forecasts",
        "n": 25,
        "per": "assembly"
      },
      "region": {
        "rule": "at most",
        "lo": 0.3
      },
      "observation": "avoidably_unresolved_share",
      "answers_for": "all",
      "reason": "A seat that keeps its commitments answerable to evidence and lets the world settle them cannot leave this share high, and the observation already excludes faultless external unobservability."
    },
    {
      "id": "burn-rate-bound",
      "norm": "durable agency",
      "description": "Compute spent in the window, metered invocations plus retained-storage rent; a card that scowls when a single window's spend is large relative to the factory's own scale.",
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 4,
        "per": null
      },
      "region": {
        "rule": "at most",
        "lo": 0.5
      },
      "observation": "burn_per_window",
      "answers_for": "all",
      "reason": "Stewardship of the resources that make future worthwhile choices possible requires a visible ceiling on how fast a window can eat them."
    },
    {
      "id": "concentration-bound",
      "norm": "bounded reciprocity",
      "description": "Largest share of a window's model calls served by one provider; a card that flags dependence on a single rail whose failure would offload its cost onto outsiders.",
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 4,
        "per": null
      },
      "region": {
        "rule": "at most",
        "lo": 0.7
      },
      "observation": "provider_concentration",
      "answers_for": "all",
      "reason": "Concentrating on one provider, like any unpaid externality, finances the factory's advantage by exposing others to a rail it does not control."
    },
    {
      "id": "measurement-fidelity-floor",
      "norm": "fidelity",
      "description": "Share of selected responses declaring noop or hold; a floor that keeps the factory from substituting a favorable activity count for the values the activity was supposed to serve.",
      "units": "fraction",
      "window": {
        "kind": "returns",
        "n": 20,
        "per": "role"
      },
      "region": {
        "rule": "at most",
        "lo": 0.6
      },
      "observation": "noop_share",
      "answers_for": "all",
      "reason": "Measurements are defeasible evidence of the values, not substitutes; a factory that reads well only by counting noop responses has stopped measuring what it claims to value."
    },
    {
      "id": "forecast-skill-floor",
      "norm": "epistemic integrity",
      "description": "Mean forecast Brier minus paired prevalence-baseline Brier; forecasts must beat the base rate or the seat is betting without having earned the right to.",
      "units": "score difference",
      "window": {
        "kind": "forecasts",
        "n": 25,
        "per": "assembly"
      },
      "region": {
        "rule": "above",
        "lo": 0.0
      },
      "observation": "forecast_skill",
      "answers_for": "all",
      "reason": "A commitment answerable to evidence must at least outperform the prevalence baseline; a changed criterion cannot rewrite what was promised, and a forecast that never beat the base rate was never a forecast."
    },
    {
      "id": "judge-agreement-ceiling",
      "norm": "fidelity",
      "description": "Mean population standard deviation across judges of the same return; a card that flags judging whose readings are so scattered that the verdict mean is not evidence of the underlying value.",
      "units": "score standard deviation",
      "window": {
        "kind": "windows",
        "n": 4,
        "per": null
      },
      "region": {
        "rule": "at most",
        "lo": 0.2
      },
      "observation": "evaluator_disagreement",
      "answers_for": "evaluator",
      "reason": "Measurements are defeasible evidence, not substitutes: when judges of the same return disagree this widely the mean verdict is a measurement artifact, not a reading of the value."
    },
    {
      "id": "censored-share-ceiling",
      "norm": "durable agency",
      "description": "Censored outcomes over resolved outcomes, including judgements and exposures; a card that charges a seat for losing the ability to discover whether its own commitments settled.",
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 6,
        "per": null
      },
      "region": {
        "rule": "at most",
        "lo": 0.4
      },
      "observation": "censored_share",
      "answers_for": "all",
      "reason": "Preserving the ability to discover that a commitment was wrong is stewardship of future capability, and a censored outcome is a capability quietly surrendered."
    },
    {
      "id": "tool-call-cost-ceiling",
      "norm": "durable agency",
      "description": "Mean attempted tool calls per selected response, failures included; a card that bounds how much of a decision's budget is spent probing rather than acting.",
      "units": "count per return",
