      "id": "judgement-resolution",
      "norm": "fidelity",
      "description": "Attributable, avoidably unresolved accepted commitments over eligible commitments due in the responsible scope; no eligible sample is unmeasured, not zero.",
      "units": "fraction",
      "window": {
        "kind": "forecasts",
        "n": 5,
        "per": "assembly"
      },
      "region": {
        "rule": "at most",
        "hi": 0.3
      },
      "observation": "avoidably_unresolved_share",
      "answers_for": "evaluator",
      "reason": "Tracking avoidable non-resolution supports answerability while excluding not-yet-due or externally unobservable commitments."
    },
    {
      "id": "compute-burden",
      "norm": "bounded reciprocity",
      "description": "Compute spent in the window, including invocation costs and retained-storage rent; use as a resource-burden signal rather than proof that outsiders were or were not harmed.",
      "units": "micro-USD per window",
      "window": {
        "kind": "windows",
        "n": 5,
        "per": null
      },
      "region": {
        "rule": "at most",
        "hi": 1000000
      },
      "observation": "burn_per_window",
      "answers_for": "all",
      "reason": "Monitoring aggregate resource use can flag burdens needing scrutiny, while the norm still requires evidence about consent and external costs."
    }
  ]
}

{
  "cards": [
    {
      "answers_for": "all",
      "description": "Mean successful response cost in the selected rows; global closed windows use successful producer returns. A retained-storage charge adds to what those responses cost and is never counted as one of them.",
      "id": "cost_per_return",
      "lambda": 0,
      "norm": "durable agency",
      "observation": "cost_per_return",
      "reason": "Stewardship requires tracking the compute resources consumed by successful operations to ensure future choices remain possible.",
      "region": {
        "rule": "at most"
      },
      "units": "micro-USD per return",
      "window": {
        "kind": "returns",
        "n": 10,
        "per": null
      }
    },
    {
      "answers_for": "producer",
      "description": "Share of selected responses declaring noop or hold; global closed windows use producer returns.",
      "id": "noop_share",
      "lambda": 0,
      "norm": "consequential usefulness",
      "observation": "noop_share",
      "reason": "Uptake by independent counterparties is evidence of value, so a high rate of non-action suggests a failure to create things others have reason to value.",
      "region": {
        "rule": "below the median of the previous window"
      },
      "units": "fraction",
      "window": {
        "kind": "returns",
        "n": 20,
        "per": "assembly"
      }
    },
    {
      "answers_for": "evaluator",
      "description": "Mean evaluator verdict; forecast selectors use the verdicts attached to resolved forecasts, grouped by the judged return's assembly or role.",
      "id": "verdict_mean",
      "lambda": 0,
      "norm": "fidelity",
      "observation": "verdict_mean",
      "reason": "Measurements are defeasible evidence of values, so tracking the mean verdict ensures that internal applause aligns with supported consequences rather than substituting for them.",
      "region": {
        "rule": "between"
      },
      "units": "score",
      "window": {
        "kind": "windows",
        "n": 5,
        "per": null
      }
    },
    {
      "answers_for": "meta",
      "description": "Compute the evaluator roles (judges, adversarial judges, every tier of meta) spent in the window over all compute spent in it, retained-storage rent included.",
      "id": "evaluator_compute_share",
      "lambda": 0,
      "norm": "bounded reciprocity",
      "observation": "evaluator_compute_share",
      "reason": "The factory must not finance its advantage by imposing unconsented costs on outsiders, so limiting the share of resources spent on self-evaluation preserves external utility.",
      "region": {
        "rule": "at most"
      },
      "units": "fraction",
      "window": {
        "kind": "windows",
        "n": 10,
        "per": null
      }
    },
    {
      "answers_for": "all",
      "description": "Censored outcomes over resolved outcomes; forecast selectors use forecast records, global closed windows also include judgements and exposures.",
      "id": "censored_share",
      "lambda": 0,
      "norm": "epistemic integrity",
      "observation": "censored_share",
      "reason": "Preserving the ability to discover that commitments were wrong requires minimizing censored outcomes where evidence cannot settle the promise.",
      "region": {
        "rule": "at most"
      },
      "units": "fraction",
      "window": {
        "kind": "forecasts",
        "n": 25,
        "per": null
      }
    }
  ]
}
